"""cam_studio.cam.tabs3d — Плавные 3D треугольные мостики (Triangular Ramp Tabs)."""

import math
from typing import List, Tuple


def apply_3d_tabs(polyline: List[Tuple[float, float]], z_bottom: float,
                  tab_height: float = 3.5, tab_width: float = 12.0,
                  num_tabs: int = 4) -> List[Tuple[float, float, float]]:
    """
    Применяет 3D треугольные мостики вдоль замкнутой полилинии контура.
    Фреза плавно поднимается на z_bottom + tab_height к вершине мостика и плавно опускается,
    позволяя станку проходить мостики на полной скорости без остановок.
    """
    if len(polyline) < 2:
        return []

    # Расчет кумулятивной длины
    total_length = 0.0
    seg_lengths = []
    for i in range(len(polyline)):
        p1 = polyline[i]
        p2 = polyline[(i + 1) % len(polyline)]
        dist = math.hypot(p2[0] - p1[0], p2[1] - p1[1])
        seg_lengths.append(dist)
        total_length += dist

    if total_length <= 0:
        return [(p[0], p[1], z_bottom) for p in polyline]

    # Равномерные центры мостиков по периметру
    tab_centers = [(total_length * (k + 0.5)) / num_tabs for k in range(num_tabs)]
    half_w = tab_width / 2.0

    result = []
    current_dist = 0.0

    for i in range(len(polyline)):
        p1 = polyline[i]
        p2 = polyline[(i + 1) % len(polyline)]
        seg_len = seg_lengths[i]
        if seg_len < 1e-6:
            continue

        # Плотность дискретизации: отрезки не более 1.5 мм для гладкого профиля
        steps = max(1, int(math.ceil(seg_len / 1.5)))
        for s in range(steps):
            t = s / float(steps)
            x = p1[0] + (p2[0] - p1[0]) * t
            y = p1[1] + (p2[1] - p1[1]) * t
            d = current_dist + seg_len * t

            z = z_bottom
            for tc in tab_centers:
                delta = abs(d - tc)
                if delta <= half_w:
                    # Треугольный подъем: 1.0 в центре, 0.0 по краям
                    ramp = 1.0 - (delta / half_w)
                    z = z_bottom + tab_height * ramp
                    break
            result.append((x, y, z))

        current_dist += seg_len

    return result
